import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();
const { fontFamily: interFamily } = loadInter();



export type WealthOffenseGraphicProps = Record<string, any>;

const WealthOffenseGraphic: React.FC<WealthOffenseGraphicProps> = ({
  backgroundColor = "#0F172A", // Deep Slate
  transparentBackground = false,
  durationInSeconds = 8,
  titlePart1 = "PRESERVING",
  titlePart2 = "WEALTH",
  subtitle = "IS A DEFENSIVE STRATEGY.",
  primaryColor = "#3B82F6", // Shield Blue (Defense/Protection)
  accentColor = "#10B981", // Emerald Green (Wealth/Origin)
  defenseColor = "#EF4444", // Red (Obstacles/Threats)
  gridColor = "rgba(255, 255, 255, 0.05)",
  pathThickness = 16,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Layout Coordinates ---
  // Left side is for text. Right side (45% to 90% width) is the "field".
  const fieldStartX = width * 0.45;
  const fieldEndX = width * 0.9;
  const fieldStartY = height * 0.75;
  const fieldEndY = height * 0.25;

  // Cubic Bezier Control Points for an "S" curve bypassing threats
  const cp1X = width * 0.65;
  const cp1Y = height * 0.75;
  const cp2X = width * 0.65;
  const cp2Y = height * 0.25;

  const trajectoryPathD = `M ${fieldStartX} ${fieldStartY} C ${cp1X} ${cp1Y}, ${cp2X} ${cp2Y}, ${fieldEndX} ${fieldEndY}`;

  // --- Animations ---
  
  // Background/Grid Fade
  const bgOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Text Animations (Staggered)
  const text1Progress = spring({ frame: frame - 5, fps, config: { damping: 14 } });
  const text2Progress = spring({ frame: frame - 12, fps, config: { damping: 14 } });
  const subtitleProgress = spring({ frame: frame - 20, fps, config: { damping: 14 } });

  const text1Y = interpolate(text1Progress, [0, 1], [50, 0]);
  const text2Y = interpolate(text2Progress, [0, 1], [50, 0]);
  const subtitleY = interpolate(subtitleProgress, [0, 1], [30, 0]);

  // Playbook Nodes (X and Os)
  const heroNodeScale = spring({ frame: frame - 25, fps, config: { damping: 12 } });
  
  const obs1Scale = spring({ frame: frame - 30, fps, config: { damping: 10 } });
  const obs2Scale = spring({ frame: frame - 33, fps, config: { damping: 10 } });
  const obs3Scale = spring({ frame: frame - 36, fps, config: { damping: 10 } });
  
  const goalNodeScale = spring({ frame: frame - 40, fps, config: { damping: 12 } });

  // Trajectory Line Draw
  // Starts after nodes are established
  const pathDrawProgress = spring({
    frame: frame - 50,
    fps,
    config: { damping: 100, mass: 2, stiffness: 40 }, // Smooth, deliberate forward motion
  });
  
  const strokeOffset = interpolate(pathDrawProgress, [0, 1], [100, 0], {
    extrapolateRight: "clamp",
  });

  // Arrowhead Pop (at the end of the line)
  const arrowHeadScale = spring({
    frame: frame - 85, // Pops near the end of the path draw
    fps,
    config: { damping: 10, mass: 0.8 },
  });

  // Obstacle Coordinates (placed to look like they are being bypassed)
  const obstacles = [
    { x: width * 0.58, y: height * 0.55, scale: obs1Scale },
    { x: width * 0.72, y: height * 0.45, scale: obs2Scale },
    { x: width * 0.82, y: height * 0.65, scale: obs3Scale },
  ];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* 1. Background Grid (The "Field") */}
      <svg width={width} height={height} style={{ opacity: bgOpacity, position: "absolute" }}>
        <defs>
          <pattern
            id="playbook-grid"
            width={80}
            height={80}
            patternUnits="userSpaceOnUse"
          >
            <path
              d="M 80 0 L 0 0 0 80"
              fill="none"
              stroke={gridColor}
              strokeWidth={2}
            />
            {/* Cross intersections */}
            <path d="M -5 0 L 5 0 M 0 -5 L 0 5" fill="none" stroke={gridColor} strokeWidth={2} />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#playbook-grid)" />
      </svg>

      {/* 2. Text Content (Left Side) */}
      <div
        style={{
          position: "absolute",
          left: width * 0.08,
          top: height * 0.35,
          display: "flex",
          flexDirection: "column",
          gap: 10,
          width: width * 0.35,
          zIndex: 10,
        }}
      >
        <div style={{ overflow: "hidden", paddingBottom: 10 }}>
          <h1
            style={{
              fontFamily: spaceGroteskFamily,
              fontSize: 110,
              fontWeight: 800,
              color: "#FFFFFF",
              margin: 0,
              lineHeight: 1,
              transform: `translateY(${text1Y}px)`,
              opacity: text1Progress,
              letterSpacing: "-0.02em",
            }}
          >
            {titlePart1}
          </h1>
        </div>
        <div style={{ overflow: "hidden", paddingBottom: 20 }}>
          <h1
            style={{
              fontFamily: spaceGroteskFamily,
              fontSize: 130,
              fontWeight: 900,
              color: primaryColor,
              margin: 0,
              lineHeight: 0.9,
              transform: `translateY(${text2Y}px)`,
              opacity: text2Progress,
              letterSpacing: "-0.03em",
              textShadow: `0 0 40px ${primaryColor}66`,
            }}
          >
            {titlePart2}
          </h1>
        </div>
        <div style={{ overflow: "hidden", marginTop: 20 }}>
          <p
            style={{
              fontFamily: interFamily,
              fontSize: 32,
              fontWeight: 600,
              color: accentColor,
              margin: 0,
              textTransform: "uppercase",
              letterSpacing: "0.1em",
              transform: `translateY(${subtitleY}px)`,
              opacity: subtitleProgress,
              borderLeft: `4px solid ${accentColor}`,
              paddingLeft: 20,
            }}
          >
            {subtitle}
          </p>
        </div>
      </div>

      {/* 3. The Playbook Graphic (Right Side) */}
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", zIndex: 5, overflow: "visible" }}
      >
        {/* Glow Filter */}
        <defs>
          <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="15" result="blur" />
            <feComposite in="SourceGraphic" in2="blur" operator="over" />
          </filter>
        </defs>

        {/* Defense Nodes (Os / Threats) */}
        {obstacles.map((obs, i) => (
          <g
            key={`obs-${i}`}
            style={{
              transform: `translate(${obs.x}px, ${obs.y}px) scale(${obs.scale})`,
              opacity: obs.scale,
            }}
          >
            <circle
              cx={0}
              cy={0}
              r={24}
              fill="none"
              stroke={defenseColor}
              strokeWidth={8}
            />
            {/* Cross inside defense for extra detail */}
            <path d="M -10 -10 L 10 10 M -10 10 L 10 -10" stroke={defenseColor} strokeWidth={4} strokeLinecap="round" opacity={0.5} />
          </g>
        ))}

        {/* Passive Strategy Line (Faint, straight line representing status quo) */}
        <path
          d={`M ${fieldStartX} ${fieldStartY} L ${fieldEndX} ${fieldStartY}`}
          fill="none"
          stroke="#FFFFFF"
          strokeWidth={4}
          strokeDasharray="10 15"
          opacity={0.15 * pathDrawProgress}
        />

        {/* Target/Goal Area */}
        <g
          style={{
            transform: `translate(${fieldEndX}px, ${fieldEndY}px) scale(${goalNodeScale})`,
            opacity: goalNodeScale,
          }}
        >
          <circle cx={0} cy={0} r={40} fill={`${primaryColor}22`} />
          <circle cx={0} cy={0} r={40} fill="none" stroke={primaryColor} strokeWidth={4} strokeDasharray="8 8" />
          <circle cx={0} cy={0} r={12} fill={primaryColor} />
        </g>

        {/* Hero Node (X) - Starting point */}
        <g
          style={{
            transform: `translate(${fieldStartX}px, ${fieldStartY}px) scale(${heroNodeScale})`,
            opacity: heroNodeScale,
          }}
        >
          <path
            d="M -20 -20 L 20 20 M -20 20 L 20 -20"
            fill="none"
            stroke={accentColor}
            strokeWidth={12}
            strokeLinecap="round"
          />
        </g>

        {/* The Defensive Strategy Trajectory (Glowing Line) */}
        <path
          d={trajectoryPathD}
          fill="none"
          stroke={primaryColor}
          strokeWidth={pathThickness}
          strokeLinecap="round"
          pathLength={100}
          strokeDasharray={100}
          strokeDashoffset={strokeOffset}
          filter="url(#glow)"
        />
        
        {/* Core Line (Solid white inside for intensity) */}
        <path
          d={trajectoryPathD}
          fill="none"
          stroke="#FFFFFF"
          strokeWidth={pathThickness * 0.3}
          strokeLinecap="round"
          pathLength={100}
          strokeDasharray={100}
          strokeDashoffset={strokeOffset}
        />

        {/* Arrowhead at the end */}
        {/* Since the curve ends horizontally (cp2Y === fieldEndY), the arrow points right */}
        <g
          style={{
            transform: `translate(${fieldEndX}px, ${fieldEndY}px) scale(${arrowHeadScale})`,
            opacity: arrowHeadScale,
          }}
        >
          <polygon
            points="0,-25 40,0 0,25"
            fill={primaryColor}
            filter="url(#glow)"
          />
          <polygon
            points="0,-15 25,0 0,15"
            fill="#FFFFFF"
          />
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default WealthOffenseGraphic;